/**
 * A single CSS dimension value, e.g. `{ value: 210, unit: "mm" }`.
 */
export interface Dimension {
	value: number;
	unit: string;
}

/**
 * A named page size definition with fixed width and height.
 */
export interface NamedPageSize {
	width: Dimension;
	height: Dimension;
}

