import Handler, { type HandlerSource } from "../handler.js";
import csstree from "css-tree";
import type { CssNode, List } from "css-tree";

interface RunningHeaderValue {
	identifier: string;
	value?: string;
	selector: string;
	first?: Element;
	last?: Element;
	start?: Element;
	carryFirst?: Element;
	hasAppeared?: boolean;
}

interface RunningHeadersData {
	[name: string]: RunningHeaderValue;
}

interface ElementContentValue {
	func: string;
	args: string[];
	value: string;
	style: string;
	selector: string;
	fullSelector: string;
}

interface ElementContentData {
	[selector: string]: ElementContentValue;
}

interface RuleContext {
	ruleNode: CssNode;
	ruleItem?: List.Cursor;
	rulelist?: List;
}

interface SheetSource {
	text?: string;
}

/**
 * Handles CSS Running Headers/Footers using the `position: running()` and `content: element()` CSS features.
 *
 * Tracks selectors with running headers, manages their capture and placement,
 * and applies them during page layout.
 *
 * @class
 * @extends Handler
 */
class RunningHeaders extends Handler {
	runningSelectors: RunningHeadersData;
	elements: ElementContentData;
	orderedSelectors?: string[];

	/**
	 * Creates an instance of RunningHeaders.
	 *
	 * @param {Object} chunker - The chunker instance controlling content chunking.
	 * @param {Object} polisher - The polisher instance controlling polishing/styling.
	 * @param {Object} caller - The caller or controller invoking this handler.
	 */
	constructor(chunker?: HandlerSource, polisher?: HandlerSource, caller?: HandlerSource) {
		super(chunker, polisher, caller);

		/**
		 * Stores running header selectors keyed by the running identifier.
		 */
		this.runningSelectors = {};

		/**
		 * Stores element() CSS content references keyed by selector string.
		 */
		this.elements = {};
	}

	/**
	 * Processes CSS declarations to find and store `position: running()` and `content: element()` rules.
	 *
	 * @param {Object} declaration - The CSS declaration node.
	 * @param {Object} dItem - Declaration item (not used here).
	 * @param {Object} dList - Declaration list (not used here).
	 * @param {Object} rule - The CSS rule node that contains the declaration.
	 */
	onDeclaration(declaration: CssNode, dItem: List.Cursor, dList: List, rule: RuleContext) {
		if (declaration.property === "position") {
			let selector = csstree.generate(rule.ruleNode.prelude);
			let identifier = declaration.value.children.first().name;

			if (identifier === "running") {
				let value: string | undefined;
				csstree.walk(declaration, {
					visit: "Function",
					enter: (node) => {
						value = node.children.first().name;
					},
				});

				this.runningSelectors[value!] = {
					identifier: identifier,
					value: value,
					selector: selector,
				};
			}
		}

		if (declaration.property === "content") {
			csstree.walk(declaration, {
				visit: "Function",
				enter: (funcNode) => {
					if (funcNode.name.indexOf("element") > -1) {
						let selector = csstree.generate(rule.ruleNode.prelude);
						let func = funcNode.name;
						let value = funcNode.children.first().name;
						let args = [value];
						let style = "first";
						let firstIdentSeen = false;

						funcNode.children.forEach((child: CssNode) => {
							if (child.type === "Identifier") {
								if (!firstIdentSeen) {
									firstIdentSeen = true;
								} else {
									style = child.name;
								}
							}
						});

						selector.split(",").forEach((s) => {
							s = s.replace(/::after|::before/, "");
							this.elements[s] = {
								func: func,
								args: args,
								value: value,
								style: style,
								selector: s,
								fullSelector: selector,
							};
						});
					}
				},
			});
		}
	}

	afterParsed(fragment: ParentNode) {
		for (let name of Object.keys(this.runningSelectors)) {
			let set = this.runningSelectors[name];
			let selected = Array.from(fragment.querySelectorAll(set.selector));

			if (set.identifier === "running") {
				for (let header of selected) {
					header.style.display = "none";
					// Mark them undisplayed so the layout walk neither counts
					// them as rendered content nor anchors page-name break
					// decisions on them.
					header.dataset.undisplayed = "undisplayed";
				}
			}
		}
	}

	afterPageLayout(fragment: HTMLElement) {
		for (let name of Object.keys(this.runningSelectors)) {
			let set = this.runningSelectors[name];
			let selected = fragment.querySelectorAll(set.selector);

			// Reset per-page values; carryFirst and hasAppeared persist.
			set.first = undefined;
			set.last = undefined;
			set.start = undefined;

			if (selected.length && set.identifier === "running") {
				set.first = selected[0];
				set.last = selected[selected.length - 1];
				set.hasAppeared = true;

				let pageContent = fragment.querySelector(".paged_page_content");
				if (pageContent) {
					let pageTop = pageContent.getBoundingClientRect().top;
					for (let el of Array.from(selected)) {
						if (Math.abs(el.getBoundingClientRect().top - pageTop) < 1) {
							set.start = el;
							break;
						}
					}
				}
				if (!set.start) {
					set.start = set.first;
				}
				if (!set.carryFirst) {
					set.carryFirst = set.first;
				}
			}
		}

		if (!this.orderedSelectors) {
			this.orderedSelectors = this.orderSelectors(this.elements);
		}

		for (let selector of this.orderedSelectors) {
			if (selector) {
				let el = this.elements[selector];
				let selected = fragment.querySelector(selector);
				if (selected) {
					let running = this.runningSelectors[el.args[0]];
					if (!running) {
						continue;
					}

					let source: Element | undefined;
					if (el.style === "last") {
						source = running.last || running.carryFirst;
					} else if (el.style === "start") {
						source = running.start || running.carryFirst;
					} else if (el.style === "first-except") {
						// Empty on any page where the running source appears.
						source = running.first ? undefined : running.carryFirst;
					} else {
						source = running.first || running.carryFirst;
					}

					if (!source) {
						// first-except intentionally leaves the margin empty on pages
						// where its running source appears; otherwise keep whatever an
						// earlier (lower-specificity) rule already placed.
						if (el.style === "first-except") {
							selected.innerHTML = "";
						}
						continue;
					}

					selected.innerHTML = ""; // Clear node
					let clone = source.cloneNode(true) as HTMLElement;
					clone.style.display = null as unknown as string;
					selected.appendChild(clone);
				}
			}
		}
	}

	/**
	 * Assigns a weight to @page selector classes for ordering.
	 *
	 * Weights:
	 * 1) page
	 * 2) left & right
	 * 3) blank
	 * 4) first & nth
	 * 5) named page
	 * 6) named left & right
	 * 7) named first & nth
	 *
	 * @param {string} [s] - The selector string.
	 * @returns {number} Weight value for ordering.
	 */
	pageWeight(s: string) {
		let weight = 1;
		let selector = s.split(" ");
		let parts = (selector.length && selector[0].split(".")) as string[];

		parts.shift(); // remove empty first part

		switch (parts.length) {
			case 4:
				if (/^paged_[\w-]+_first_page$/.test(parts[3])) {
					weight = 7;
				} else if (
					parts[3] === "paged_left_page" ||
					parts[3] === "paged_right_page"
				) {
					weight = 6;
				}
				break;
			case 3:
				if (parts[1] === "paged_named_page") {
					if (parts[2].indexOf(":nth-of-type") > -1) {
						weight = 7;
					} else {
						weight = 5;
					}
				}
				break;
			case 2:
				if (parts[1] === "paged_first_page") {
					weight = 4;
				} else if (parts[1] === "paged_blank_page") {
					weight = 3;
				} else if (
					parts[1] === "paged_left_page" ||
					parts[1] === "paged_right_page"
				) {
					weight = 2;
				}
				break;
			default:
				if (parts[0].indexOf(":nth-of-type") > -1) {
					weight = 4;
				} else {
					weight = 1;
				}
		}

		return weight;
	}

	/**
	 * Orders selectors based on their page weight.
	 *
	 * Does not deduplicate selectors; later selectors overwrite previous ones.
	 *
	 * @param {Object<string, any>} obj - The selectors object.
	 * @returns {Array<string>} Ordered selectors array.
	 */
	orderSelectors(obj: ElementContentData) {
		let selectors = Object.keys(obj);
		let weighted: { [weight: number]: string[] } = {
			1: [],
			2: [],
			3: [],
			4: [],
			5: [],
			6: [],
			7: [],
		};

		let orderedSelectors: string[] = [];

		for (let s of selectors) {
			let w = this.pageWeight(s);
			weighted[w].unshift(s);
		}

		for (let i = 1; i <= 7; i++) {
			orderedSelectors = orderedSelectors.concat(weighted[i]);
		}

		return orderedSelectors;
	}

	/**
	 * Adjusts CSS text before parsing.
	 *
	 * Fixes parsing issues with `element()` by renaming it to `element-ident()`.
	 *
	 * @param {string} text - The CSS text to parse.
	 * @param {Object} sheet - The CSS stylesheet object.
	 */
	beforeTreeParse(text: string, sheet: SheetSource) {
		// element(x) is parsed as image element selector, so update element to element-ident
		sheet.text = text.replace(
			/element[\s]*\(([^|^#)]*)\)/g,
			"element-ident($1)",
		);
	}
}

export default RunningHeaders;
